const usage = $('Code in JavaScript1').first().json;
const inventoryItems = $input.all();

for (const item of inventoryItems) {
  const row = item.json;
  const itemName = (row["Item Name"] || "").trim();
  const usedQty = usage[itemName] || 0;

  if (usedQty > 0) {
    row["In-Stock"] = Math.max(0, (Number(row["In-Stock"]) || 0) - usedQty);}
}

return inventoryItems;

