const order = $('Append row in sheet').first().json;

const componentsRows = $input.all().map(item => item.json);

const totalUsage = {
  "Bread": 0,
  "onino": 0,
  "tomato": 0,
  "Beef slice": 0,
  "Chicken slice": 0,
  "Chesse": 0
};

// 4. المرور على كل سندوتش في الأوردر وحساب استهلاكه
for (const [key, qty] of Object.entries(order)) {
  const quantity = Number(qty);

  // تجاهل الحقول غير الرقمية أو السندوتشات التي كميتها 0
  if (isNaN(quantity) || quantity <= 0) continue;

  // البحث عن السندوتش في شيت المكونات مع تجاهل حالة الأحرف والمسافات
  const recipe = componentsRows.find(
    row => row["Item Name"] && row["Item Name"].trim().toLowerCase() === key.trim().toLowerCase()
  );

  if (recipe) {
    totalUsage["Bread"] += (Number(recipe["Bread"]) || 0) * quantity;
    totalUsage["onino"] += (Number(recipe["onino"]) || 0) * quantity;
    totalUsage["tomato"] += (Number(recipe["tomato"]) || 0) * quantity;
    totalUsage["Beef slice"] += (Number(recipe["Beef slice "] ?? recipe["Beef slice"]) || 0) * quantity;
    totalUsage["Chicken slice"] += (Number(recipe["Chicken slice "] ?? recipe["Chicken slice"]) || 0) * quantity;
    totalUsage["Chesse"] += (Number(recipe["Chesse"]) || 0) * quantity;
  }
}

return [{ json: totalUsage }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
