  return b
}

// 1. تعريف المنيو الأساسي بـ أصفار
let finalOrder = {
  "Beef Burger": 0,
  "Chicken Burger": 0,
  "Chesse Beef Burger": 0,
  "chesse Chicken Burger": 0
};

// 2. اللف على كل الـ Items اللي داخلة للـ Node
let items = $input.all();

for (let item of items) {
    let data = item.json;

    if (data.Name !== undefined && data.Quntity !== undefined) {
        if (finalOrder[data.Name] !== undefined) {
            finalOrder[data.Name] = data.Quntity;
        }
    }
}


return [{
  json: finalOrder
}];

